access_register_session.definition:
CREATE OR REPLACE FUNCTION public.access_register_session(p_user uuid, p_session uuid, p_account uuid, p_generation integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a private.enterprise_accounts;begin
 perform pg_advisory_xact_lock(734921501);
 if p_session is null then return false;end if;
 perform private.require_eligible_user(p_user);
 if p_account is null then
 if not exists(select 1 from public.platform_roles where user_id=p_user and active) then return false;end if;
 else
 select * into a from private.enterprise_accounts where id=p_account and user_id=p_user and state='active' and generation=p_generation;
 if a.id is null or (a.organization_id is not null and not exists(select 1 from public.organization_members m join public.organizations o on o.id=m.organization_id where m.user_id=p_user and m.organization_id=a.organization_id and m.status='active' and o.status='active')) then return false;end if;
 end if;
 insert into private.access_enforced_users values(p_user) on conflict do nothing;
 insert into private.enterprise_sessions(session_id,user_id,organization_id,account_id,generation) values(p_session,p_user,a.organization_id,a.id,a.generation) on conflict do nothing;
 return true;end;$function$

access_session.definition:
CREATE OR REPLACE FUNCTION public.access_session(p_activity boolean DEFAULT false, p_logout boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s private.enterprise_sessions;begin
 if p_logout then update private.enterprise_sessions set revoked=true where user_id=auth.uid()and session_id::text=auth.jwt()->>'session_id';return '{}'::jsonb;end if;
 if auth.uid()is null then raise exception 'session_expired'using errcode='42501';end if;
 if not private.access_base_active()then raise exception 'account_inactive'using errcode='42501';end if;
 select * into s from private.enterprise_sessions where user_id=auth.uid()and session_id::text=auth.jwt()->>'session_id';
 if s.organization_id is not null and exists(select 1 from public.organizations where id=s.organization_id and status<>'active')then raise exception 'organization_suspended'using errcode='42501';end if;
 if not private.access_session_valid(false)then raise exception 'session_expired'using errcode='42501';end if;
 if p_activity then update private.enterprise_sessions set last_activity=clock_timestamp()where session_id=s.session_id returning * into s;end if;
 return jsonb_build_object('idle_seconds',(select idle_seconds from private.access_policy),'warning_seconds',(select warning_seconds from private.access_policy),'last_activity',s.last_activity,'organization_id',s.organization_id,'organization_name',(select name from public.organizations where id=s.organization_id),
 'legal_required',s.organization_id is not null and not private.legal_ready(s.organization_id),'verification_required',s.organization_id is not null and not private.verification_ready(s.organization_id),
 'can_accept',exists(select 1 from public.organization_members where organization_id=s.organization_id and user_id=auth.uid()and role='admin_empresa'and status='active'));
end;$function$

access_reserve.definition:
CREATE OR REPLACE FUNCTION public.access_reserve(p_org uuid, p_name text, p_slug text, p_display text, p_username text, p_email text, p_phone text, p_role text, p_key uuid, p_existing uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 perform private.lock_authorize(case when p_org is null then 'global' else 'org' end,p_org);
 if p_org is not null and not private.company_can_manage(p_org) then raise exception 'access_denied' using errcode='42501';end if;
 if p_org is not null and not exists(select 1 from public.organizations where id=p_org and status='active') then raise exception 'access_denied';end if;
 return public.access_reserve_026(p_org,p_name,p_slug,p_display,p_username,p_email,p_phone,p_role,p_key,p_existing);end;$function$

access_finish_provision.definition:
CREATE OR REPLACE FUNCTION public.access_finish_provision(p_id uuid, p_actor uuid, p_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a private.enterprise_accounts;begin
 perform pg_advisory_xact_lock(734921501);select * into a from private.enterprise_accounts where id=p_id for update;
 if a.id is null or a.state<>'reserved' or a.requested_by<>p_actor or not ((a.organization_id is null and private.people_root(p_actor))or private.inviter_eligible(a.organization_id,p_actor)) or p_hash is null or p_hash !~ '^[a-f0-9]{64}$' then raise exception 'access_denied';end if;
 if (select count(*) from public.organization_members where user_id=a.user_id)>1 and not exists(select 1 from public.platform_roles where user_id=p_actor and role='super_admin' and active) then raise exception 'shared_identity_requires_superadmin';end if;
 perform private.require_eligible_user(a.user_id);
 insert into private.access_enforced_users values(a.user_id) on conflict do nothing;
 update private.enterprise_accounts set state='pending',code_hash=p_hash,code_expires=clock_timestamp()+make_interval(hours=>(select code_hours from private.access_policy)) where id=p_id;
 if a.organization_id is not null then insert into public.organization_members(organization_id,user_id,role,is_attendant) values(a.organization_id,a.user_id,case when a.role='admin_empresa' then 'admin_empresa'::public.member_role else 'colaborador_empresa'::public.member_role end,a.role='own_attendant') on conflict(organization_id,user_id) do nothing;end if;
 update public.profiles set display_name=a.display_name where id=a.user_id;
 perform private.access_audit(a.organization_id,p_actor,'access_provisioned',a.id);
 return jsonb_build_object('company_code',coalesce((select code from private.enterprise_codes where organization_id=a.organization_id),'SYZIA'),'company_name',(select name from public.organizations where id=a.organization_id),'username',a.username,'expires_at',(select code_expires from private.enterprise_accounts where id=p_id));end;$function$

foundation_create_organization.definition:
CREATE OR REPLACE FUNCTION public.foundation_create_organization(p_name text, p_slug text, p_admin uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare org uuid;
begin
 perform private.lock_authorize('global');
 perform private.require_eligible_user(p_admin);
 insert into public.organizations(name,slug) values(btrim(p_name),p_slug) returning id into org;
 insert into public.organization_members(organization_id,user_id,role) values(org,p_admin,'admin_empresa');
 return org;
end; $function$

access_verify_document.definition:
CREATE OR REPLACE FUNCTION public.access_verify_document(p_org uuid, p_kind text, p_document text, p_revision integer, p_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d text;fp bytea;v private.organization_verifications;prior private.verification_commands;k text;why text;r jsonb;begin
 perform pg_advisory_xact_lock(734921501);
 if not private.verification_administrator(p_org)then raise exception 'access_denied' using errcode='42501';end if;
 d=private.document_normalize(p_kind,p_document);if d is null or p_key is null then raise exception 'document_invalid' using errcode='22023';end if;
 fp=private.trial_fingerprint('registration','BR:'||p_kind||':'||d);
 select * into prior from private.verification_commands where organization_id=p_org and actor_id=auth.uid() and key=p_key;
 if found then if prior.fingerprint<>fp then raise exception 'idempotency_conflict';end if;return prior.result;end if;
 select * into v from private.organization_verifications where organization_id=p_org for update;
 if v.revision is distinct from p_revision then raise exception 'verification_revision_conflict' using errcode='40001';end if;
 if v.state='verified' and v.fingerprint is distinct from fp then raise exception 'verification_review_required';end if;
 if not exists(select 1 from private.organization_exemptions where organization_id=p_org and state='active') then
 foreach k in array case when p_kind='CPF'then array['business','responsible']else array['business']end loop
 insert into private.trial_identifiers(organization_id,kind,fingerprint,verified_by,evidence_ref) values(p_org,k,private.trial_fingerprint(k,'BR:'||p_kind||':'||d),auth.uid(),'self_declared_structure_030')on conflict do nothing;
 insert into private.trial_claims select id,k,private.trial_fingerprint(k,'BR:'||p_kind||':'||d)from private.trial_grants where organization_id=p_org on conflict do nothing;
 end loop;
 insert into private.trial_consumed_keys select distinct on(c.kind,c.fingerprint)c.kind,c.fingerprint,c.grant_id from private.trial_claims c join private.trial_grants g on g.id=c.grant_id where g.organization_id=p_org order by c.kind,c.fingerprint,c.grant_id on conflict do nothing;
 end if;
 why=private.trial_eligibility(p_org);
 update private.organization_verifications set state=case when why in('manual_policy','previous_review')then 'review'else 'verified'end,kind=p_kind,masked=case when p_kind='CPF'then '***.***.***-'else '**.***.***/****-'end||right(d,2),fingerprint=fp,verified_by=auth.uid(),verified_at=clock_timestamp(),revision=revision+1 where organization_id=p_org;
 perform private.access_audit(p_org,auth.uid(),'registration_structure_checked',p_org);
 r=public.access_verification_context(p_org);insert into private.verification_commands values(p_org,auth.uid(),p_key,fp,r);return r;
end;$function$

billing_subscription_action.definition:
CREATE OR REPLACE FUNCTION public.billing_subscription_action(p_org uuid, p_action text, p_plan uuid, p_revision integer, p_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare why text;s public.billing_subscriptions;v public.billing_plan_versions;prior public.billing_commands;payload jsonb;result_ jsonb;request_ uuid;begin
 perform private.company_lock(p_org); if private.internal_exemption(p_org) is not null then raise exception 'exemption_no_subscription';end if;
 if p_action is distinct from 'trial' then return private.billing_subscription_action_base(p_org,p_action,p_plan,p_revision,p_key);end if;
 if p_key is null then raise exception 'billing_key_required' using errcode='22023';end if;
 payload=jsonb_build_object('action',p_action,'plan',p_plan,'revision',p_revision);
 select * into prior from public.billing_commands where organization_id=p_org and actor_id=auth.uid() and key=p_key;
 if found then if prior.payload<>payload then raise exception 'billing_key_conflict' using errcode='22023';end if;return prior.result;end if;
 select * into s from public.billing_subscriptions where organization_id=p_org;
 if s.organization_id is not null or p_revision is distinct from 0 then return private.billing_subscription_action_base(p_org,p_action,p_plan,p_revision,p_key);end if;
 select pv.* into v from public.billing_plans p join public.billing_plan_versions pv on pv.plan_id=p.id and pv.version=p.revision where p.id=p_plan and p.active and p.available;
 if v.id is null or v.trial_days=0 then raise exception 'billing_trial_unavailable' using errcode='22023';end if;
 why=private.trial_eligibility(p_org);
 if why='eligible' then
 begin
 result_=private.billing_subscription_action_base(p_org,p_action,p_plan,p_revision,p_key);
 select * into s from public.billing_subscriptions where organization_id=p_org;
 perform private.trial_record(p_org,s.plan_version_id,s.period_start,s.period_end,'automatic','Verified eligibility under current policy');
 update private.trial_requests set state='approved',revision=revision+1,decision_reason='Verified automatic eligibility',decided_at=clock_timestamp() where organization_id=p_org and state='pending';
 return result_;
 exception when unique_violation then why='previous_identity'; end;
 end if;
 select id into request_ from private.trial_requests where organization_id=p_org and state='pending';
 if request_ is null then
 insert into private.trial_requests(organization_id,plan_id,actor_id,risk_reason) values(p_org,p_plan,auth.uid(),why) returning id into request_;
 insert into private.trial_audit(organization_id,actor_id,action,details) values(p_org,auth.uid(),'review_requested',jsonb_build_object('request',request_,'risk',why));end if;
 result_=jsonb_build_object('review_required',true,'request_id',request_);
 insert into public.billing_commands values(p_org,auth.uid(),p_key,payload,result_,now());
 return result_;
end;$function$

billing_apply_event.definition:
CREATE OR REPLACE FUNCTION private.billing_apply_event(p_event text, p_invoice uuid, p_state text, p_amount integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare i public.billing_invoices;s public.billing_subscriptions;v public.billing_plan_versions;prior public.billing_webhooks;payload jsonb;res jsonb;begin
 perform pg_advisory_xact_lock(734921501);
 if not (select mock_enabled from private.billing_runtime) then raise exception 'billing_mock_disabled' using errcode='42501';end if;
 if p_event is null or length(p_event) not between 8 and 160 or p_state not in ('paid','failed','overdue','cancelled','refunded') or p_state is null then raise exception 'billing_event_invalid' using errcode='22023';end if;
 payload=jsonb_build_object('invoice',p_invoice,'state',p_state,'amount',p_amount,'provider','mock');select * into prior from public.billing_webhooks where event_id=p_event;
 if found then if prior.payload<>payload then raise exception 'billing_key_conflict' using errcode='22023';end if;return prior.result;end if;
 select * into i from public.billing_invoices where id=p_invoice for update;
 if not found or p_amount is distinct from i.amount_cents then raise exception 'billing_invoice_invalid' using errcode='22023';end if;
 select * into s from public.billing_subscriptions where organization_id=i.organization_id for update;
 if i.state=p_state then res=jsonb_build_object('duplicate',true,'simulation',true);
 else
 if not (i.state='pending' and p_state in ('paid','failed','overdue','cancelled') or i.state='paid' and p_state='refunded') then raise exception 'billing_transition_invalid' using errcode='22023';end if;
 if p_state='paid' and (s.state='suspended' or s.revision<>i.subscription_revision) then raise exception 'billing_revision_conflict' using errcode='40001';end if;
 update public.billing_invoices set state=p_state,paid_at=case when p_state='paid' then now() else paid_at end where id=i.id;
 if p_state='paid' then
 select * into v from public.billing_plan_versions where id=i.plan_version_id;
 update public.billing_subscriptions set plan_version_id=v.id,pending_version_id=null,state='active',period_start=now(),period_end=now()+make_interval(months=>v.interval_months),cancel_at_end=false,revision=revision+1 where organization_id=i.organization_id;
 elsif p_state in ('failed','overdue') and (s.state='pending' or s.period_end<=now()) then update public.billing_subscriptions set state='past_due',revision=revision+1 where organization_id=i.organization_id;
 end if;
 -- Refund records the simulated financial fact; does not silently cancel an unrelated/current entitlement.
 perform private.billing_event(i.organization_id,'mock_'||p_state,i.id,jsonb_build_object('simulation',true));res=jsonb_build_object('state',p_state,'simulation',true);
 end if;
 insert into public.billing_webhooks(event_id,organization_id,invoice_id,payload,result) values(p_event,i.organization_id,i.id,payload,res);return res;
end;$function$

billing_plan_save.definition:
CREATE OR REPLACE FUNCTION public.billing_plan_save(p_id uuid, p_revision integer, p_data jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare id_ uuid;rev integer;begin
 perform private.lock_authorize('global');
 perform private.company_keys(p_data,array['name','description','active','available','position','price_cents','interval_months','trial_days','human_support','commercial_followups','member_limit','service_limit','request_limit','ticket_limit','followup_limit','capabilities']);
 if p_id is null then
 if p_revision is distinct from 0 then raise exception 'billing_revision_conflict' using errcode='40001';end if;
 insert into public.billing_plans(name,description,active,available,position) values(p_data->>'name',coalesce(p_data->>'description',''),coalesce((p_data->>'active')::boolean,true),coalesce((p_data->>'available')::boolean,false),coalesce((p_data->>'position')::integer,0)) returning id,revision into id_,rev;
 else
 update public.billing_plans set name=p_data->>'name',description=coalesce(p_data->>'description',''),active=coalesce((p_data->>'active')::boolean,true),available=coalesce((p_data->>'available')::boolean,false),position=coalesce((p_data->>'position')::integer,0),revision=revision+1 where id=p_id and revision=p_revision returning id,revision into id_,rev;
 if not found then raise exception 'billing_revision_conflict' using errcode='40001';end if;
 end if;
 insert into public.billing_plan_versions(plan_id,version,price_cents,interval_months,trial_days,human_support,commercial_followups,member_limit,service_limit,request_limit,ticket_limit,followup_limit,capabilities)
 values(id_,rev,(p_data->>'price_cents')::integer,(p_data->>'interval_months')::integer,coalesce((p_data->>'trial_days')::integer,0),coalesce((p_data->>'human_support')::boolean,false),coalesce((p_data->>'commercial_followups')::boolean,true),(p_data->>'member_limit')::integer,(p_data->>'service_limit')::integer,(p_data->>'request_limit')::integer,(p_data->>'ticket_limit')::integer,(p_data->>'followup_limit')::integer,coalesce(p_data->'capabilities','{}'::jsonb));
 return id_;
end;$function$

foundation_context.definition:
CREATE OR REPLACE FUNCTION public.foundation_context()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
 if not private.is_active_user() then raise exception 'access_denied' using errcode='42501'; end if;
 select jsonb_build_object(
 'profile',(select to_jsonb(p) from public.profiles p where id=auth.uid()),
 'roles',coalesce((select jsonb_agg(role) from public.platform_roles where user_id=auth.uid() and active),'[]'::jsonb),
 'organizations',coalesce((select jsonb_agg(to_jsonb(o) order by name) from public.organizations o),'[]'::jsonb),
 'identity',public.people_self(),'memberships',coalesce((select jsonb_agg(to_jsonb(m)) from public.organization_members m where user_id=auth.uid()),'[]'::jsonb)
 ) into result;
 return result;
end; $function$
